import{_ as n,a0 as p,w as d,s as o,I as i,x as a,a1 as l,A as t,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"举例说明 alias 和 unalias 命令 | LCTT x X-CMD","titleTemplate":false,"description":"举例说明 alias 和 unalias 命令 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"举例说明 alias 和 unalias 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"举例说明 alias 和 unalias 命令 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181113 The alias And unalias Commands Explained With Examples","title":"举例说明 alias 和 unalias 命令","tag":"201811","desc":""},"relativePath":"201811/20181113 The alias And unalias Commands Explained With Examples.md","filePath":"[post].md"}'),r={name:"201811/20181113 The alias And unalias Commands Explained With Examples.md"};function u(g,s,k,b,c,m){const e=p("Link");return d(),o("div",null,[s[28]||(s[28]=i("h1",{id:"举例说明-alias-和-unalias-命令",tabindex:"-1"},[a("举例说明 alias 和 unalias 命令 "),i("a",{class:"header-anchor",href:"#举例说明-alias-和-unalias-命令","aria-label":"Permalink to “举例说明 alias 和 unalias 命令”"},"​")],-1)),s[29]||(s[29]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/11/alias-command-720x340.png",alt:""})],-1)),i("p",null,[s[3]||(s[3]=a("如果不是一个命令行重度用户的话，过了一段时间之后，你就可能已经忘记了这些复杂且冗长的 Linux 命令了。当然，有很多方法可以让你 ",-1)),l(e,{href:"https://www.ostechnix.com/easily-recall-forgotten-linux-commands/"},{default:t(()=>[...s[0]||(s[0]=[a("回想起遗忘的命令",-1)])]),_:1}),s[4]||(s[4]=a("。你可以简单的 ",-1)),l(e,{href:"https://www.ostechnix.com/save-commands-terminal-use-demand/"},{default:t(()=>[...s[1]||(s[1]=[a("保存常用的命令",-1)])]),_:1}),s[5]||(s[5]=a(" 然后按需使用。也可以在终端里 ",-1)),l(e,{href:"https://www.ostechnix.com/bookmark-linux-commands-easier-repeated-invocation/"},{default:t(()=>[...s[2]||(s[2]=[a("标记重要的命令",-1)])]),_:1}),s[6]||(s[6]=a("，然后在任何时候你想要的时间使用它们。而且，Linux 有一个内建命令 ",-1)),s[7]||(s[7]=i("code",null,"history",-1)),s[8]||(s[8]=a(" 可以帮助你记忆这些命令。另外一个记住这些如此长的命令的简便方式就是为这些命令创建一个别名。你可以为任何经常重复调用的常用命令创建别名，而不仅仅是长命令。通过这种方法，你不必再过多地记忆这些命令。这篇文章中，我们将会在 Linux 环境下举例说明 ",-1)),s[9]||(s[9]=i("code",null,"alias",-1)),s[10]||(s[10]=a(" 和 ",-1)),s[11]||(s[11]=i("code",null,"unalias",-1)),s[12]||(s[12]=a(" 命令。",-1))]),s[30]||(s[30]=h(`<h3 id="alias-命令" tabindex="-1">alias 命令 <a class="header-anchor" href="#alias-命令" aria-label="Permalink to “alias 命令”">​</a></h3><p><code>alias</code> 使用一个用户自定义的字符串来代替一个或者一串命令（包括多个选项、参数）。这个字符串可以是一个简单的名字或者缩写，不管这个命令原来多么复杂。<code>alias</code> 命令已经预装在 shell（包括 BASH、Csh、Ksh 和 Zsh 等） 当中。</p><p><code>alias</code> 的通用语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias [alias-name[=string]...]</span></span></code></pre></div><p>接下来看几个例子。</p><h4 id="列出别名" tabindex="-1">列出别名 <a class="header-anchor" href="#列出别名" aria-label="Permalink to “列出别名”">​</a></h4><p>可能在你的系统中已经设置了一些别名。有些应用在你安装它们的时候可能已经自动创建了别名。要查看已经存在的别名，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias -p</span></span></code></pre></div><p>在我的 Arch Linux 系统中已经设置了下面这些别名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias betty=&#39;/home/sk/betty/main.rb&#39;</span></span>
<span class="line"><span>alias ls=&#39;ls --color=auto&#39;</span></span>
<span class="line"><span>alias pbcopy=&#39;xclip -selection clipboard&#39;</span></span>
<span class="line"><span>alias pbpaste=&#39;xclip -selection clipboard -o&#39;</span></span>
<span class="line"><span>alias update=&#39;newsbeuter -r &amp;&amp; sudo pacman -Syu&#39;</span></span></code></pre></div><h4 id="创建一个新的别名" tabindex="-1">创建一个新的别名 <a class="header-anchor" href="#创建一个新的别名" aria-label="Permalink to “创建一个新的别名”">​</a></h4><p>像我之前说的，你不必去记忆这些又臭又长的命令。你甚至不必一遍一遍的运行长命令。只需要为这些命令创建一个简单易懂的别名，然后在任何你想使用的时候运行这些别名就可以了。这种方式会让你爱上命令行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -h --max-depth=1 | sort -hr</span></span></code></pre></div><p>这个命令将会查找当前工作目录下的各个子目录占用的磁盘大小，并按照从大到小的顺序进行排序。这个命令有点长。我们可以像下面这样轻易地为其创建一个 别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias du=&#39;du -h --max-depth=1 | sort -hr&#39;</span></span></code></pre></div><p>这里的 <code>du</code> 就是这条命令的别名。这个别名可以被设置为任何名字，主要便于记忆和区别。</p><p>在创建一个别名的时候，使用单引号或者双引号都是可以的。这两种方法最后的结果没有任何区别。</p><p>现在你可以运行这个别名（例如我们这个例子中的 <code>du</code> ）。它和上面的原命令将会产生相同的结果。</p><p>这个别名仅限于当前 shell 会话中。一旦你退出了当前 shell 会话，别名也就失效了。为了让这些别名长久有效，你需要把它们添加到你 shell 的配置文件当中。</p><p>BASH，编辑 <code>~/.bashrc</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.bashrc</span></span></code></pre></div><p>一行添加一个别名：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/alias.png" alt=""></p><p>保存并退出这个文件。然后运行以下命令更新修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>现在，这些别名在所有会话中都可以永久使用了。</p><p>ZSH，你需要添加这些别名到 <code>~/.zshrc</code>文件中。Fish，跟上面的类似，添加这些别名到 <code>~/.config/fish/config.fish</code> 文件中。</p><h4 id="查看某个特定的命令别名" tabindex="-1">查看某个特定的命令别名 <a class="header-anchor" href="#查看某个特定的命令别名" aria-label="Permalink to “查看某个特定的命令别名”">​</a></h4><p>像我上面提到的，你可以使用 <code>alias</code> 命令列出你系统中所有的别名。如果你想查看跟给定的别名有关的命令，例如 <code>du</code>，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias du</span></span>
<span class="line"><span>alias du=&#39;du -h --max-depth=1 | sort -hr&#39;</span></span></code></pre></div><p>像你看到的那样，上面的命令可以显示与单词 <code>du</code> 有关的命令。</p><p>关于 <code>alias</code> 命令更多的细节，参阅 man 手册页：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man alias</span></span></code></pre></div><h3 id="unalias-命令" tabindex="-1">unalias 命令 <a class="header-anchor" href="#unalias-命令" aria-label="Permalink to “unalias 命令”">​</a></h3><p>跟它的名字说的一样，<code>unalias</code> 命令可以很轻松地从你的系统当中移除别名。<code>unalias</code> 命令的通用语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unalias &lt;alias-name&gt;</span></span></code></pre></div><p>要移除命令的别名，像我们之前创建的 <code>du</code>，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias du</span></span></code></pre></div><p><code>unalias</code> 命令不仅会从当前会话中移除别名，也会从你的 shell 配置文件中永久地移除别名。</p><p>还有一种移除别名的方法，是创建具有相同名称的新别名。</p><p>要从当前会话中移除所有的别名，使用 <code>-a</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias -a</span></span></code></pre></div><p>更多细节，参阅 man 手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man unalias</span></span></code></pre></div><p>如果你经常一遍又一遍的运行这些繁杂又冗长的命令，给它们创建别名可以节省你的时间。现在是你为常用命令创建别名的时候了。</p><p>这就是所有的内容了。希望可以帮到你。还有更多的干货即将到来，敬请期待！</p><p>祝近祺！</p><hr>`,50)),i("p",null,[s[14]||(s[14]=a("via: ",-1)),l(e,{href:"https://www.ostechnix.com/the-alias-and-unalias-commands-explained-with-examples/"},{default:t(()=>[...s[13]||(s[13]=[a("https://www.ostechnix.com/the-alias-and-unalias-commands-explained-with-examples/",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=a("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[15]||(s[15]=[a("SK",-1)])]),_:1}),s[20]||(s[20]=a(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[a("lujun9972",-1)])]),_:1}),s[21]||(s[21]=a(" 译者：",-1)),l(e,{href:"https://github.com/dianbanjiu"},{default:t(()=>[...s[17]||(s[17]=[a("dianbanjiu",-1)])]),_:1}),s[22]||(s[22]=a(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[a("Linux中国",-1)])]),_:1}),s[27]||(s[27]=a(" 荣誉推出",-1))])])}const C=n(r,[["render",u]]);export{y as __pageData,C as default};
